import sys

def min_rest_days(n, activities):
    # Initialize DP tables
    dp_rest = [float('inf')] * n
    dp_contest = [float('inf')] * n
    dp_sport = [float('inf')] * n

    # Base cases
    if activities[0] == 0:
        dp_rest[0] = 1
    else:
        dp_rest[0] = 0

    if activities[0] == 1 or activities[0] == 3:
        dp_contest[0] = 1
    else:
        dp_contest[0] = 0

    if activities[0] == 2 or activities[0] == 3:
        dp_sport[0] = 1
    else:
        dp_sport[0] = 0

    # Fill DP tables
    for i in range(1, n):
        if activities[i] == 0:
            dp_rest[i] = min(dp_rest[i-1] + 1, dp_contest[i-1], dp_sport[i-1])
        elif activities[i] == 1:
            dp_contest[i] = min(dp_contest[i-1] + 1, dp_rest[i-1], dp_sport[i-1])
        elif activities[i] == 2:
            dp_sport[i] = min(dp_sport[i-1] + 1, dp_rest[i-1], dp_contest[i-1])
        elif activities[i] == 3:
            dp_contest[i] = min(dp_contest[i-1] + 1, dp_rest[i-1])
            dp_sport[i] = min(dp_sport[i-1] + 1, dp_rest[i-1])

    # Find the minimum rest days
    return min(dp_rest[-1], dp_contest[-1], dp_sport[-1])

